// The capsule decoder — ported from backend/dhruva/codec/codec.py's decode().
//
// PURE: no network, no filesystem, no clock. The whole claim of this project is
// that a phone with its radio off can expand a capsule into a spoken advisory,
// and a decoder that reaches for anything at all breaks that on the day it
// matters. decode.test.ts greps this file's source for exactly the imports
// that would break it.
//
// eval/capsule_corpus.jsonl (500 rows, generated by the Python side) is the
// contract: every row here must decode to the identical Capsule Python does.

import {
  BOUNDARY_TYPES,
  CAPSULE_BYTES,
  CHL_CLASSES,
  FIELDS,
  fromRaw,
  HAZARD_FLAGS,
  MSG_TYPES,
  RISK_CLASSES,
  TOTAL_BITS,
  ZONE_LAT_MIN,
  ZONE_LON_CELLS,
  ZONE_LON_MIN,
  ZONE_STEP,
} from "./fields";

export interface Capsule {
  msg_type: string;
  schema_ver: number;
  issue_slot: number;
  valid_hours: number;
  lat: number;
  lon: number;
  risk_class: string;
  hazards: string[];
  wave_hs_m: number;
  wind_kt: number;
  wind_dir_deg: number;
  curr_kt: number;
  curr_dir_deg: number;
  sst_c: number;
  chl_class: string;
  pfz_bearing_deg: number;
  pfz_dist_nm: number;
  pfz_conf: number;
  bnd_dist_nm: number;
  bnd_type: string;
  bnd_eta_min: number;
  reason_code: number;
  evidence_hash: number;
  /** Always empty from decode(): saturation is encode-time-only information
   * about the ORIGINAL value that a wire capsule cannot carry. codec.py's own
   * decode() never sets this either — it is a dataclass default that survives
   * untouched — so this mirrors that rather than inferring it after the fact. */
  saturated: string[];
}

/** (index % 16) * 22.5 — matches codec/fields.py's index_to_bearing exactly,
 * rather than going through the generic scale/offset path, because that is
 * what the Python decoder itself does for every compass field. */
function indexToBearing(index: number): number {
  return (index % 16) * 22.5;
}

function zoneBounds(zoneId: number): [lat: number, lon: number] {
  const latIdx = Math.floor(zoneId / ZONE_LON_CELLS);
  const lonIdx = zoneId % ZONE_LON_CELLS;
  return [ZONE_LAT_MIN + latIdx * ZONE_STEP, ZONE_LON_MIN + lonIdx * ZONE_STEP];
}

function fieldsToPosition(zoneId: number, latOffset: number, lonOffset: number): [number, number] {
  const [baseLat, baseLon] = zoneBounds(zoneId);
  return [baseLat + (latOffset / 256) * ZONE_STEP, baseLon + (lonOffset / 256) * ZONE_STEP];
}

function bitmapHazards(value: number): string[] {
  const out: string[] = [];
  for (let i = 0; i < HAZARD_FLAGS.length; i++) {
    if (value & (1 << (HAZARD_FLAGS.length - 1 - i))) out.push(HAZARD_FLAGS[i]);
  }
  return out;
}

function roundTo(value: number, digits: number): number {
  const factor = 10 ** digits;
  return Math.round(value * factor) / factor;
}

/** 19 bytes to a Capsule. */
export function decode(payload: Uint8Array): Capsule {
  if (payload.length !== CAPSULE_BYTES) {
    throw new Error(`capsule must be ${CAPSULE_BYTES} bytes, got ${payload.length}`);
  }

  // BigInt, not number: 145 bits vastly exceeds Number.MAX_SAFE_INTEGER
  // (2^53-1), so a plain JS number would silently lose precision partway
  // through the shift chain. Every extracted per-field raw value is small
  // enough (max width 20 bits) to convert back to a regular number safely.
  let acc = 0n;
  for (const byte of payload) {
    acc = (acc << 8n) | BigInt(byte);
  }
  acc >>= BigInt(CAPSULE_BYTES * 8 - TOTAL_BITS);

  const raw: Record<string, number> = {};
  for (let i = FIELDS.length - 1; i >= 0; i--) {
    const f = FIELDS[i];
    const mask = (1n << BigInt(f.width)) - 1n;
    raw[f.name] = Number(acc & mask);
    acc >>= BigInt(f.width);
  }

  const [lat, lon] = fieldsToPosition(raw.zone_id, raw.lat_offset, raw.lon_offset);

  return {
    // width 4 (16 raw values) but only 4 names — modulo guards a future raw
    // value this table has not caught up with yet, exactly as decode() does.
    msg_type: MSG_TYPES[raw.msg_type % MSG_TYPES.length],
    schema_ver: raw.schema_ver,
    issue_slot: raw.issue_slot,
    valid_hours: raw.valid_hours,
    lat,
    lon,
    risk_class: RISK_CLASSES[raw.risk_class],
    hazards: bitmapHazards(raw.hazard_flags),
    wave_hs_m: fromRaw("wave_hs", raw.wave_hs),
    wind_kt: raw.wind_kt,
    wind_dir_deg: indexToBearing(raw.wind_dir),
    curr_kt: roundTo(fromRaw("curr_kt", raw.curr_kt), 4),
    curr_dir_deg: indexToBearing(raw.curr_dir),
    sst_c: fromRaw("sst", raw.sst),
    chl_class: CHL_CLASSES[raw.chl_class],
    pfz_bearing_deg: indexToBearing(raw.pfz_bearing),
    pfz_dist_nm: raw.pfz_dist_nm,
    pfz_conf: raw.pfz_conf,
    bnd_dist_nm: raw.bnd_dist_nm,
    bnd_type: BOUNDARY_TYPES[raw.bnd_type],
    bnd_eta_min: raw.bnd_eta_min,
    reason_code: raw.reason_code,
    evidence_hash: raw.evidence_hash,
    saturated: [],
  };
}

/** For QR: base32, uppercase, unpadded — RFC 4648 with the trailing "=" runs
 * stripped, matching codec.py's from_base32/to_base32 exactly. */
const BASE32_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";

export function decodeBase32(text: string): Uint8Array {
  const clean = text.trim().toUpperCase().replace(/=+$/, "");
  let bits = "";
  for (const char of clean) {
    const value = BASE32_ALPHABET.indexOf(char);
    if (value === -1) throw new Error(`invalid base32 character: ${char}`);
    bits += value.toString(2).padStart(5, "0");
  }
  const bytes = new Uint8Array(Math.floor(bits.length / 8));
  for (let i = 0; i < bytes.length; i++) {
    bytes[i] = Number.parseInt(bits.slice(i * 8, i * 8 + 8), 2);
  }
  return bytes;
}

export function decodeHexBytes(text: string): Uint8Array {
  const clean = text.trim();
  if (clean.length % 2 !== 0) throw new Error("hex string must have an even length");
  const bytes = new Uint8Array(clean.length / 2);
  for (let i = 0; i < bytes.length; i++) {
    bytes[i] = Number.parseInt(clean.slice(i * 2, i * 2 + 2), 16);
  }
  return bytes;
}

/** Capsule in, base32 or hex in, Capsule out — the two entry points a QR scan
 * or an SMS payload actually needs. */
export function decodeCapsule(base32: string): Capsule {
  return decode(decodeBase32(base32));
}

export function decodeHex(hex: string): Capsule {
  return decode(decodeHexBytes(hex));
}
